mapper.select:
SELECT situation_db_tool.*, attachment.file_name as file_name, attachment.file_path as file_path
FROM situation_db_tool
left join attachment on
situation_db_tool.attachment = attachment.resource_id
WHERE 1 = 1

    AND situation_db_tool.name LIKE concat("%", #{situationDbToolFilterReq.pattern} ,"%")


    AND situation_db_tool.tool_type = #{situationDbToolFilterReq.category}


    AND situation_db_tool.update_time > #{situationDbToolFilterReq.startTime}


    AND situation_db_tool.update_time < #{situationDbToolFilterReq.endTime}

ORDER BY create_time DESC
